+async fn within<T>(phase: Phase, limit: Duration, operation: impl Future<Output = io::Result<T>>) -> Result<T, DeadlineError> {
+    let mut timer = Box::pin(tokio::time::sleep(limit));
+    let mut operation = Box::pin(operation);
+    std::future::poll_fn(move |cx| {
+        if timer.as_mut().poll(cx).is_ready() {
+            return std::task::Poll::Ready(Err(DeadlineError::Elapsed { phase, limit }));
+        }
+        match operation.as_mut().poll(cx) {
+            std::task::Poll::Pending => std::task::Poll::Pending,
+            std::task::Poll::Ready(value) => std::task::Poll::Ready(value.map_err(|e| DeadlineError::Stream(StreamError::Io(e)))),
+        }
+    }).await
 }

